#include <variant>
#include <vector>
#include <map>
#include <string>
#include <sstream>
#include <type_traits>
struct Node { std::variant<std::monostate, bool, int64_t, std::string, std::vector<Node>, std::map<std::string,Node>> val; };
std::string dbg_node(const Node& n) {
    return std::visit([](auto&& x) -> std::string {
        using T = std::decay_t<decltype(x)>;
        if constexpr (std::is_same_v<T, std::monostate>) return "null";
        else if constexpr (std::is_same_v<T, bool>) return x ? "true" : "false";
        else if constexpr (std::is_same_v<T, int64_t>) return std::to_string(x);
        else if constexpr (std::is_same_v<T, std::string>) return x;
        else if constexpr (std::is_same_v<T, std::vector<Node>>) {
            std::ostringstream oss; oss << "["; bool first=true;
            for (auto& e : x) { if(!first) oss << ","; oss << dbg_node(e); first=false; }
            oss << "]"; return oss.str();
        } else {
            std::ostringstream oss; bool first=true;
            for (auto& kv : x) { if(!first) oss << ","; oss << kv.first << "=" << dbg_node(kv.second); first=false; }
            return oss.str();
        }
    }, n.val);
}
